# 新疆生产建设兵团不是自治区财政厅地州分表中的普通地级行政单元，
# 但其地方政府债务由财政部和兵团财政公开披露。这里接入兵团全域余额，
# 映射到行政区划主表中的 659000“自治区直辖县级行政区划”占位行。
# 2021 年为上一年度实际数，2022—2023 年为公开表中的预计执行数，
# 2024 年为自治区财政厅决算说明披露的年末余额；不将其与新疆自治区本级合并。
