def _slice(text: str, start: str, end: str | None = None, occurrence: int = 1) -> str:
    start_at = -1
    cursor = 0
    for _ in range(max(1, occurrence)):
        start_at = text.find(start, cursor)
        if start_at < 0:
            return ""
        cursor = start_at + len(start)
    end_at = text.find(end, start_at + len(start)) if end else -1
    return text[start_at:] if end_at < 0 else text[start_at:end_at]


def _source_configs() -> Iterable[dict[str, Any]]:
    for source in OFFICIAL_PROVINCE_DEBT_SOURCES:
        if source.get("components"):
            for component in source["components"]:
                config = dict(source)
                config.update(component)
                yield config
        else:
            yield source


def _extract_ceic_secondary_debt_facts(
    city_master: list[Mapping[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """读取已归档的 CEIC 城市页次级补缺值，不把未返回页解释成零。"""
    if not CEIC_SECONDARY_DEBT_PATH.exists():
        return [], []
    # city_master is a city×roster-year table, while the secondary file is a
    # city×metric-year table.  A city can therefore appear in city_master only
    # for one roster snapshot even though its debt observations cover several
    # metric years.  Validate the stable city identity here and keep the
    # metric-year range check explicit instead of requiring an accidental
    # city×year pair in the roster table.
    valid_city_ids = {str(city["city_id"]) for city in city_master}
    province_by_city_id = {
        str(city["city_id"]): str(city.get("province_name", ""))
        for city in city_master
    }
    rows: list[dict[str, Any]] = []
    source_configs: dict[str, dict[str, Any]] = {}
    with CEIC_SECONDARY_DEBT_PATH.open(encoding="utf-8-sig", newline="") as handle:
        for line_number, item in enumerate(csv.DictReader(handle), start=2):
            city_id = str(item.get("city_id", ""))
            year = str(item.get("metric_year", ""))
            if city_id not in valid_city_ids or not year.isdigit() or not 2018 <= int(year) <= 2025:
                continue
            value = Decimal(item["statutory_debt_balance_100m"]) if item.get("statutory_debt_balance_100m") else None
            if value is None:
                continue
            source_doc_id = str(item.get("source_doc_id", ""))
            rows.append(
                {
                    "city_id": city_id,
                    "city_name_cn": str(item.get("city_name_cn", "")),
                    "province_name": province_by_city_id.get(city_id, ""),
                    "metric_year": year,
                    "geo_scope": "prefecture_whole",
                    "source_doc_id": source_doc_id,
                    "line_number": line_number,
                    "table_name": "CEIC 城市级地方政府债务余额页面/图表",
                    "evidence_excerpt": str(item.get("evidence_excerpt", "")),
                    "unit_factor": Decimal("1"),
                    "value_origin": str(item.get("value_origin", "disclosed")),
                    "raw_value_million_rmb": item.get("raw_value_million_rmb", ""),
                    "source_url": str(item.get("source_url", "")),
                    "source_grade": "D",
                    "general_debt_limit_100m": None,
                    "general_debt_balance_100m": None,
                    "special_debt_limit_100m": None,
                    "special_debt_balance_100m": None,
                    "statutory_debt_limit_100m": None,
                    "statutory_debt_balance_100m": value,
                }
            )
            source_configs.setdefault(
                source_doc_id,
                {
                    "source_doc_id": source_doc_id,
                    "province_name": "全国",
                    "year": 2025,
                    "period_end": "2025-12-31",
                    "path": CEIC_SECONDARY_DEBT_PATH,
                    "text_path": CEIC_SECONDARY_DEBT_PATH,
                    "source_url": str(item.get("source_url", "")),
                    "document_title": f"CEIC 城市级地方政府债务余额公开页面：{item.get('city_name_cn', '')}",
                    "publication_date": "2026-08-01",
                    "publisher": "CEIC Data",
                    "publisher_level": "商业数据库",
                    "source_grade": "D",
                    "unit": "亿元（由百万元人民币换算）",
                    "note": "商业聚合数据库公开页面；2018—2024 年值来自页面 SVG 图表，2025 年值来自页面元数据。仅作补缺线索和 provisional 暂存，必须回到财政厅、人大预算/决算或官方统计公报复核，不作为最终 A/B/C 级证据。",
                },
            )
    return rows, list(source_configs.values())


def _extract_rating_chart_secondary_debt_facts(
    city_master: list[Mapping[str, Any]],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    """读取评级报告公开图表转录的城市债务余额补缺值。

    这类值必须显式保留 ``chart_digitized`` 来源标记：图表柱形高度可以用于
    阶段性补缺，但不应被误读为财政厅原表的逐元精确值。CSV 只接受城市主表
    中已经存在的 ``city_id + metric_year``，避免把区县或非目标行政单元带入全国面板。
    """
    if not RATING_CHART_SECONDARY_DEBT_PATH.exists():
        return [], []
    valid_city_ids = {str(city["city_id"]) for city in city_master}
    province_by_city_id = {
        str(city["city_id"]): str(city.get("province_name", ""))
        for city in city_master
    }
    rows: list[dict[str, Any]] = []
    source_configs: dict[str, dict[str, Any]] = {}
    with RATING_CHART_SECONDARY_DEBT_PATH.open(encoding="utf-8", newline="") as handle:
        for line_number, item in enumerate(csv.DictReader(handle), start=2):
            city_id = str(item.get("city_id", ""))
            year = str(item.get("metric_year", ""))
            if city_id not in valid_city_ids or not year.isdigit() or not 2018 <= int(year) <= 2025:
                continue
            raw_value = str(item.get("statutory_debt_balance_100m", "")).strip()
            if not raw_value:
                continue
            try:
                value = Decimal(raw_value)
            except Exception:
                continue
            source_doc_id = str(item.get("source_doc_id", ""))
            source_grade = str(item.get("source_grade") or "B2")
            value_origin = str(item.get("value_origin") or "chart_digitized")
            source_url = str(item.get("source_url", ""))
            city_name = str(item.get("city_name_cn", ""))
            rows.append(
                {
                    "city_id": city_id,
                    "city_name_cn": city_name,
                    "province_name": province_by_city_id.get(city_id, str(item.get("province_name", ""))),
                    "metric_year": year,
                    "geo_scope": "prefecture_whole",
                    "source_doc_id": source_doc_id,
                    "line_number": line_number,
                    "table_name": str(item.get("table_name") or "评级报告公开图表：各地级市政府债务余额"),
                    "evidence_excerpt": str(item.get("evidence_excerpt", "")),
                    "unit_factor": Decimal("1"),
                    "value_origin": value_origin,
                    "source_url": source_url,
                    "source_grade": source_grade,
                    "general_debt_limit_100m": None,
                    "general_debt_balance_100m": None,
                    "special_debt_limit_100m": None,
                    "special_debt_balance_100m": None,
                    "statutory_debt_limit_100m": None,
                    "statutory_debt_balance_100m": value,
                }
            )
            source_configs.setdefault(
                source_doc_id,
                {
                    "source_doc_id": source_doc_id,
                    "province_name": str(item.get("province_name") or province_by_city_id.get(city_id, "")),
                    "year": int(year) if year.isdigit() else year,
                    "period_end": str(item.get("period_end") or f"{year}-12-31"),
                    "path": RATING_CHART_SECONDARY_DEBT_PATH,
                    "text_path": RATING_CHART_SECONDARY_DEBT_PATH,
                    "source_url": source_url,
                    "document_title": str(item.get("document_title") or "评级机构地方政府债务风险研究报告（图表转录）"),
                    "publication_date": str(item.get("publication_date") or "2026-08-01"),
                    "publisher": str(item.get("publisher") or "评级机构研究报告"),
                    "publisher_level": "评级机构研究报告",
                    "source_grade": source_grade,
                    "unit": "亿元",
                    "note": str(item.get("source_note") or "图表柱形高度按公开纵轴刻度转录，仅作阶段性补缺；不等同于官方财政决算表，待官方附件复核。"),
                },
            )
    return rows, list(source_configs.values())


def extract_official_debt_facts(city_master: list[Mapping[str, Any]]) -> tuple[dict[tuple[str, str], dict[str, Any]], list[dict[str, Any]]]:
    """从已归档的官方文本中提取可直接接入主表的事实和来源元数据。"""
    names_by_province_year: dict[tuple[str, int], set[str]] = {}
    city_id_by_province_name_year: dict[tuple[str, str, int], str] = {}
    for city in city_master:
        year = int(city["metric_year"])
        key = (str(city["province_name"]), year)
        names_by_province_year.setdefault(key, set()).add(str(city["city_name_cn"]))
        city_id_by_province_name_year[(str(city["province_name"]), str(city["city_name_cn"]), year)] = str(city["city_id"])

    fact_rows: list[dict[str, Any]] = []
    source_rows: list[dict[str, Any]] = []
    aliases_by_province_year: dict[tuple[str, int], dict[str, str]] = {}
    for config in _source_configs():
        text_path = Path(config["text_path"])
        if not text_path.exists():
            continue
        segment = ""
        if config.get("format") != "xlsx":
            text = text_path.read_text(encoding="utf-8")
            segment = _slice(
                text,
                str(config.get("start", "")),
                config.get("end"),
                int(config.get("start_occurrence", 1)),
            )
            if not segment:
                continue
        province = str(config["province_name"])
        year = int(config["year"])
        aliases = {str(k): str(v) for k, v in (config.get("aliases") or {}).items()}
        aliases_by_province_year[(province, year)] = aliases
        factor = config.get("unit_factor", Decimal("1"))
        layout = str(config.get("layout", "component2" if config.get("component") else "total6"))
        expected_names = set(names_by_province_year.get((province, year), set())) | set(aliases)
        if config.get("format") == "xlsx":
            rows = extract_xlsx_city_rows(
                text_path,
                expected_names,
                year,
                province,
                str(config["source_doc_id"]),
                unit_factor=factor,
                table_name=str(config.get("table_name", "")),
                sheet_path=str(config.get("sheet_path", "xl/worksheets/sheet1.xml")),
                name_column=str(config.get("name_column", "C")),
                value_columns=tuple(config.get("value_columns", ("D", "E", "F", "G", "H", "I"))),
                layout=layout,
            )
        else:
            rows = extract_city_rows(
                segment,
                expected_names,
                year,
                province,
                str(config["source_doc_id"]),
                layout=layout,
                component=config.get("component"),
                unit_factor=factor,
                table_name=str(config.get("table_name", "")),
            )
        for row in rows:
            raw_city_name = str(row["city_name_cn"])
            canonical_city_name = aliases.get(raw_city_name, raw_city_name)
            if canonical_city_name != raw_city_name:
                row["city_name_cn"] = canonical_city_name
            city_id = city_id_by_province_name_year.get((province, canonical_city_name, year))
            if city_id is None:
                continue
            row["city_id"] = city_id
            row["source_grade"] = str(config.get("source_grade", "A1"))
            # 个别官方决算公开表在发布时仍标注“预计执行数”。保留来源的
            # 数据状态，避免在主表中把预执行数误标为最终决算数。
            if config.get("data_status"):
                row["data_status"] = str(config["data_status"])
            if config.get("value_origin"):
                row["value_origin"] = str(config["value_origin"])
            exception_note = str(config.get("balance_limit_exception_note") or "")
            exception_note_by_city = {
                str(name): str(note)
                for name, note in (config.get("balance_limit_exception_by_city") or {}).items()
            }
            if canonical_city_name in exception_note_by_city:
                exception_note = exception_note_by_city[canonical_city_name]
            if exception_note:
                row["balance_limit_exception_note"] = exception_note
            fact_rows.append(row)
        source_rows.append(config)

    rating_rows, rating_sources = _extract_rating_chart_secondary_debt_facts(city_master)
    fact_rows.extend(rating_rows)
    source_rows.extend(rating_sources)

    secondary_rows, secondary_sources = _extract_ceic_secondary_debt_facts(city_master)
    fact_rows.extend(secondary_rows)
    source_rows.extend(secondary_sources)

    facts_by_key: dict[tuple[str, str], dict[str, Any]] = {}
    for row in merge_debt_rows(fact_rows):
        city_id = next(
            (
                item["city_id"]
                for item in fact_rows
                if item["city_name_cn"] == row["city_name_cn"]
                and item.get("province_name") == row.get("province_name")
                and item["metric_year"] == row["metric_year"]
                and item.get("city_id")
            ),
            None,
        )
        if city_id:
            row["city_id"] = city_id
            facts_by_key[(city_id, str(row["metric_year"]))] = row
    return facts_by_key, source_rows


